package local.tvmorph.tv;
import android.app.*;import android.os.*;import android.content.*;import android.media.*;import android.webkit.*;import org.json.*;import java.io.*;import java.util.*;
public class RadioActivity extends Activity {
 static volatile RadioActivity active;private WebView web;private JSONArray stations;private RadioPlayback playback;private final RadioPlayback.Listener playbackListener=(id,state,message)->js("if(window.RadioUI)RadioUI.restore("+playback.status().toString()+")");
 static JSONArray catalog(Context c)throws Exception{try(InputStream in=c.getAssets().open("radio/stations.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new JSONArray(out.toString("UTF-8"));}}
 private String t(String ar,String en){return UiSettings.text(this,ar,en);}private String name(JSONObject s){return t(s.optString("name"),s.optString("nameEn"));}
 @Override public void onCreate(Bundle state){super.onCreate(state);playback=RadioPlayback.get(this);try{stations=catalog(this);}catch(Exception e){stations=new JSONArray();}web=new WebView(this);setContentView(web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setUseWideViewPort(true);s.setSupportZoom(false);s.setBuiltInZoomControls(false);s.setDisplayZoomControls(false);s.setTextZoom(100);s.setLoadWithOverviewMode(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setAllowUniversalAccessFromFileURLs(true);s.setMediaPlaybackRequiresUserGesture(false);web.addJavascriptInterface(new Bridge(),"RadioNative");web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}@Override public void onReceivedSslError(WebView v,SslErrorHandler h,android.net.http.SslError e){h.cancel();}});web.loadUrl("file:///android_asset/radio/index.html");}
 private void startAlternate(String id){if(active==this&&!isFinishing()&&ParentalTimer.allow(this,"local.tvmorph.tv.radio"))playback.playAlternate(id);}
 private void js(String expression){if(web!=null)web.evaluateJavascript(expression,null);} public final class Bridge{@JavascriptInterface public String catalogJson(){return stations.toString();}@JavascriptInterface public String initialStation(){return getIntent().getStringExtra("station")==null?"":getIntent().getStringExtra("station");}@JavascriptInterface public String performanceMode(){return UiSettings.prefs(RadioActivity.this).getString("performanceMode","light");}@JavascriptInterface public String deviceInfo(){try{return DeviceCapabilities.info(RadioActivity.this).toString();}catch(Exception e){return "{}";}}@JavascriptInterface public String settingsJson(){try{return UiSettings.get(RadioActivity.this).toString();}catch(Exception e){return "{}";}}@JavascriptInterface public String favoritesJson(){JSONArray ids=new JSONArray();for(int i=0;i<stations.length();i++){String id=stations.optJSONObject(i).optString("id");if(getSharedPreferences("radio"+(UiSettings.prefs(RadioActivity.this).getString("viewerId","default").equals("default")?"":"@"+UiSettings.prefs(RadioActivity.this).getString("viewerId","default")),0).getBoolean("fav:"+id,false))ids.put(id);}return ids.toString();}@JavascriptInterface public void favorite(String id,boolean value){for(int i=0;i<stations.length();i++)if(stations.optJSONObject(i).optString("id").equals(id))getSharedPreferences("radio"+(UiSettings.prefs(RadioActivity.this).getString("viewerId","default").equals("default")?"":"@"+UiSettings.prefs(RadioActivity.this).getString("viewerId","default")),0).edit().putBoolean("fav:"+id,value).apply();}@JavascriptInterface public void play(String id){runOnUiThread(()->{playback.play(id);});}@JavascriptInterface public void alternate(String id){runOnUiThread(()->startAlternate(id));}@JavascriptInterface public void toggle(){runOnUiThread(()->playback.toggle());}@JavascriptInterface public String playbackJson(){return playback.status().toString();}@JavascriptInterface public void stop(){runOnUiThread(()->{playback.stop();});}@JavascriptInterface public void exit(){runOnUiThread(()->finish());}}
 void key(String key){js("if(window.RadioUI)RadioUI.remote("+JSONObject.quote(key)+")");}
 @Override protected void onResume(){super.onResume();active=this;playback.attach(playbackListener);}@Override public void onBackPressed(){finish();}@Override protected void onPause(){if(active==this)active=null;playback.detach(playbackListener);super.onPause();}@Override protected void onDestroy(){if(web!=null)web.destroy();super.onDestroy();}
}
